const TOOLS = [
  {
    name: 'users_get_many',
    description: 'Look up multiple users by ID. Returns one line per requested ID.',
    inputSchema: {
      type: 'object',
      properties: {
        user_ids: {
          type: 'array',
          items: { type: 'string' },
          minItems: 1,
          maxItems: 5,
          uniqueItems: true,
        },
      },
      required: ['user_ids'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  const tool = TOOLS.find((t) => t.name === name);
  if (!tool) throw new Error(`Tool not found: ${name}`);

  // Validate input against schema
  validateInput(tool.inputSchema, args);

  if (name === 'users_get_many') {
    const { user_ids } = args;
    const lines = user_ids.map((id) => {
      const user = users[id];
      if (user) {
        return `${id}: ${user.name}`;
      }
      return `${id}: missing`;
    });
    return {
      content: [{ type: 'text', text: lines.join('\n') }],
    };
  }

  throw new Error(`Tool not found: ${name}`);
}

function validateInput(schema, args) {
  // Check required fields
  if (schema.required) {
    for (const field of schema.required) {
      if (!(field in args)) {
        throw new Error(`Missing required field: ${field}`);
      }
    }
  }

  // Check no additional properties
  if (schema.additionalProperties === false) {
    for (const key of Object.keys(args)) {
      if (!(key in schema.properties)) {
        throw new Error(`Unexpected field: ${key}`);
      }
    }
  }

  // Validate each property
  for (const [key, value] of Object.entries(args)) {
    const propSchema = schema.properties[key];
    if (!propSchema) continue;

    if (propSchema.type === 'array') {
      if (!Array.isArray(value)) {
        throw new Error(`Field ${key} must be an array`);
      }
      if (propSchema.minItems !== undefined && value.length < propSchema.minItems) {
        throw new Error(`Field ${key} must have at least ${propSchema.minItems} item(s)`);
      }
      if (propSchema.maxItems !== undefined && value.length > propSchema.maxItems) {
        throw new Error(`Field ${key} must have at most ${propSchema.maxItems} item(s)`);
      }
      if (propSchema.uniqueItems) {
        const seen = new Set();
        for (const item of value) {
          if (seen.has(item)) {
            throw new Error(`Field ${key} contains duplicate: ${item}`);
          }
          seen.add(item);
        }
      }
      if (propSchema.items && propSchema.items.type === 'string') {
        for (const item of value) {
          if (typeof item !== 'string') {
            throw new Error(`Field ${key} must contain only strings`);
          }
        }
      }
    }
  }
}
